import assert from 'node:assert/strict';
import {ToyRoomPhase} from '../src/js/toy-room/ToyRoomPhase.js';
import {ARENA_ENEMIES} from '../src/js/toy-room/ArenaEnemies.js';
import {updateArenaEnemyAI} from '../src/js/toy-room/ArenaEnemyAI.js';
const make=()=>{const r=new ToyRoomPhase({width:960,height:540,getContext:()=>({}),removeEventListener(){}},null,null,()=>{},{bindInputs:false,arenaEnabled:true});r.story.state.swordEquipped=true;for(let i=0;i<310;i++)r.update();return r;};
for(const actor of Object.keys(ARENA_ENEMIES))for(const side of [-1,1])for(const dt of [.5,1,3]) {
 const r=make(),b=r.battle,s=b.state,e=s.enemy;e.actor=actor;e.hp=4;e.maxHp=4;e.state='ATTACK';e.attack='Rush';e.elapsed=54;e.x=800;e.facing=-side;
 s.immunity=10000;r.player.x=800-side*(b.getEnemyCollisionDistance(actor)+1);r.keysDown={[side>0?'ArrowRight':'ArrowLeft']:true};
 const p=ARENA_ENEMIES[actor];b.presentation.enemies={...ARENA_ENEMIES,[actor]:{...p,chargeSpeed:800}};
 for(let i=0;i<8;i++){
  b.update(dt);assert.ok(side*(e.x-r.player.x)>=b.getEnemyCollisionDistance(actor)-1e-8,'Sem penetração ou inversão de lado em investida');
  assert.ok(r.player.x-56>=b.tuning.left-1e-8&&r.player.x+56<=b.tuning.right+1e-8);assert.ok(e.x-p.bodyWidth/2>=b.tuning.left-1e-8&&e.x+p.bodyWidth/2<=b.tuning.right+1e-8);
 }
 const saved=r.snapshot(),restored=make();restored.restore(saved);restored.update();assert.ok(Math.abs(restored.player.x-restored.battle.state.enemy.x)>=b.getEnemyCollisionDistance(actor)-1e-8,'Save conserva separação');r.destroy();restored.destroy();
}
let previousRest=100,previousSpeed=0;
for(const [actor,p]of Object.entries(ARENA_ENEMIES)) {
 assert.ok(p.idleTime<previousRest&&p.speed>previousSpeed,'Progressão de pressão e ritmo');previousRest=p.idleTime;previousSpeed=p.speed;
 const e={actor,x:800,hp:3,state:'APPROACH',elapsed:0,facing:-1};
 const b={state:{enemy:e,attackTime:12,jump:0},room:{player:{x:600},story:{state:{attackDirection:1}}},presentation:{enemies:ARENA_ENEMIES},tuning:{left:160,right:1440},getEnemyCollisionDistance:()=>150,setEnemyState(state){e.state=state;e.elapsed=0;},beginEnemyAttack(attack){e.state='ATTACK';e.attack=attack;}};
 if(actor==='train'){assert.equal(updateArenaEnemyAI(b,1),false);continue;}
 assert.ok(p.evadeSpeed>6.2,'Evasão temporariamente supera corrida da menina');assert.equal(updateArenaEnemyAI(b,1),true);assert.equal(e.state,'EVADE');
 const start=e.x;for(let i=0;i<p.evadeTime;i++){e.elapsed++;updateArenaEnemyAI(b,1);}
 assert.ok(e.x>start,'Foge para longe da espada');assert.equal(e.state,'ATTACK','Contra-ataca após recuar');assert.equal(e.counterAttacks,1);
 e.state='APPROACH';assert.equal(updateArenaEnemyAI(b,1),false,'Cooldown impede fuga invencível');
 const copy=JSON.parse(JSON.stringify(b.state));assert.equal(copy.enemy.evadeCooldown,e.evadeCooldown,'Decisão persiste no snapshot');
}
console.log('APROVADO: 24 cenários de corpos sólidos/investidas/bordas/save, progressão do trem ao Urso, evasão mais rápida, contra-ataque e cooldown vulnerável.');
